import React, { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  const inc = () => setCount(count + 1);
  const dec = () => setCount(Math.max(0, count - 1));

  return (
    <main style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h1>Counter</h1>
      <p data-testid="value">{count}</p>
      <button onClick={dec} aria-label="decrement">-</button>
      <button onClick={inc} aria-label="increment">+</button>
    </main>
  );
}

import React from 'react';
import './App.css';

export default function App() {
  const [name, setName] = React.useState('');
  const [email, setEmail] = React.useState('');
  const [message, setMessage] = React.useState('');

  const [touchedName, setTouchedName] = React.useState(false);
  const [touchedEmail, setTouchedEmail] = React.useState(false);
  const [touchedMessage, setTouchedMessage] = React.useState(false);

  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [successMessage, setSuccessMessage] = React.useState('');
  const [errorMessage, setErrorMessage] = React.useState('');

  const nameIsValid = name.trim().length > 0;
  const emailIsValid = /\S+@\S+\.\S+/.test(email);
  const messageIsValid = message.trim().length >= 10;
  const formIsValid = nameIsValid && emailIsValid && messageIsValid;

  const handleSubmit = async (event) => {
    event.preventDefault();

    setTouchedName(true);
    setTouchedEmail(true);
    setTouchedMessage(true);

    setSuccessMessage('');
    setErrorMessage('');

    if (!formIsValid) {
      return;
    }

    setIsSubmitting(true);

    try {
      const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ name, email, message }),
      });

      if (!response.ok) {
        throw new Error('Request failed');
      }

      setSuccessMessage('Your message has been sent. Thank you!');
      setName('');
      setEmail('');
      setMessage('');
      setTouchedName(false);
      setTouchedEmail(false);
      setTouchedMessage(false);
    } catch (err) {
      setErrorMessage('Something went wrong. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <main className="main">
      <section className="section">
        <h1>Contact Us</h1>

        <form className="panel" noValidate onSubmit={handleSubmit}>
          <div className="field">
            <label htmlFor="name">Name</label>
            <input
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onBlur={() => setTouchedName(true)}
            />
            {touchedName && !nameIsValid && (
              <p className="error">Name is required.</p>
            )}
          </div>

          <div className="field">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onBlur={() => setTouchedEmail(true)}
            />
            {touchedEmail && !email && (
              <p className="error">Email is required.</p>
            )}
            {touchedEmail && email && !emailIsValid && (
              <p className="error">Enter a valid email address.</p>
            )}
          </div>

          <div className="field">
            <label htmlFor="message">Message</label>
            <textarea
              id="message"
              rows={4}
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onBlur={() => setTouchedMessage(true)}
            />
            {touchedMessage && !message && (
              <p className="error">Message is required.</p>
            )}
            {touchedMessage && message && !messageIsValid && (
              <p className="error">Message should be at least 10 characters.</p>
            )}
          </div>

          <button
            type="submit"
            className="primary"
            disabled={!formIsValid || isSubmitting}
          >
            {isSubmitting ? 'Sending…' : 'Send message'}
          </button>

          {successMessage && <p className="success">{successMessage}</p>}
          {errorMessage && <p className="error">{errorMessage}</p>}
        </form>
      </section>
    </main>
  );
}

import React from 'react';
import './App.css';

const SLIDES = [
  {
    id: 1,
    title: 'Snowflakes glowing under city lights',
    imageUrl: 'https://picsum.photos/seed/slide-1/800/400'
  },
  {
    id: 2,
    title: 'Forest trail in the morning',
    imageUrl: 'https://images.pexels.com/photos/1563604/pexels-photo-1563604.jpeg'
  },
  {
    id: 3,
    title: 'City lights at night',
    imageUrl: 'https://images.pexels.com/photos/220067/pexels-photo-220067.jpeg'
  }
];

export default function App() {
  const [currentIndex, setCurrentIndex] = React.useState(0);

  const totalSlides = SLIDES.length;
  const currentSlide = SLIDES[currentIndex];

  const canGoPrev = currentIndex > 0;
  const canGoNext = currentIndex < totalSlides - 1;

  const goTo = (index) => {
    if (index < 0 || index >= totalSlides) return;
    setCurrentIndex(index);
  };

  const prev = () => {
    if (!canGoPrev) return;
    setCurrentIndex((i) => i - 1);
  };

  const next = () => {
    if (!canGoNext) return;
    setCurrentIndex((i) => i + 1);
  };

  return (
    <main className="main">
      <section className="section">
        <h1>Image Slider</h1>

        <figure className="frame">
          <img
            className="image"
            src={currentSlide.imageUrl}
            alt={currentSlide.title}
          />
          <figcaption className="caption">{currentSlide.title}</figcaption>
        </figure>

        <div className="meta">
          Slide {currentIndex + 1} of {totalSlides}
        </div>

        <div className="actions">
          <button type="button" onClick={prev} disabled={!canGoPrev}>
            Previous
          </button>
          <button type="button" onClick={next} disabled={!canGoNext}>
            Next
          </button>
        </div>

        <div className="dots">
          {SLIDES.map((slide, index) => (
            <button
              key={slide.id}
              type="button"
              className={
                'dot' + (index === currentIndex ? ' dot--active' : '')
              }
              onClick={() => goTo(index)}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      </section>
    </main>
  );
}

import React from 'react';
import './App.css';

type TabId = 'overview' | 'details' | 'settings';

export default function App() {
  const [activeTab, setActiveTab] = React.useState<TabId>('overview');

  const isActive = (tab: TabId) => activeTab === tab;
  const selectTab = (tab: TabId) => {
    setActiveTab(tab);
  };

  return (
    <main className="shell">
      <section className="card">
        <h1>Tabs / Multi-View Switcher</h1>
        <p className="subtitle">
          Click the tabs to switch between different content panels.
        </p>

        <nav className="tabs" aria-label="Example tabs">
          <button
            className={isActive('overview') ? 'tab active' : 'tab'}
            onClick={() => selectTab('overview')}
          >
            Overview
          </button>
          <button
            className={isActive('details') ? 'tab active' : 'tab'}
            onClick={() => selectTab('details')}
          >
            Details
          </button>
          <button
            className={isActive('settings') ? 'tab active' : 'tab'}
            onClick={() => selectTab('settings')}
          >
            Settings
          </button>
        </nav>

        {isActive('overview') && (
          <section className="panel" aria-label="Overview content">
            <h2>Overview</h2>
            <p>Show a short summary or welcome message in this panel.</p>
          </section>
        )}

        {isActive('details') && (
          <section className="panel" aria-label="Details content">
            <h2>Details</h2>
            <p>Render some more detailed information here.</p>
          </section>
        )}

        {isActive('settings') && (
          <section className="panel" aria-label="Settings content">
            <h2>Settings</h2>
            <p>Display simple settings-like text or placeholders in this panel.</p>
          </section>
        )}
      </section>
    </main>
  );
}

import React, { useState } from 'react';

const USERS = [
  { id: 1, name: 'Alice Johnson', role: 'admin', active: true },
  { id: 2, name: 'Bob Smith', role: 'editor', active: false },
  { id: 3, name: 'Charlie Kim', role: 'viewer', active: true },
  { id: 4, name: 'Dana Patel', role: 'editor', active: true },
  { id: 5, name: 'Elliot Brown', role: 'viewer', active: false }
];

export default function App() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRole, setSelectedRole] = useState('all');
  const [showOnlyActive, setShowOnlyActive] = useState(false);

  const filteredUsers = USERS.filter((user) => {
    const term = searchTerm.trim().toLowerCase();

    if (term && !user.name.toLowerCase().includes(term)) {
      return false;
    }

    if (selectedRole !== 'all' && user.role !== selectedRole) {
      return false;
    }

    if (showOnlyActive && !user.active) {
      return false;
    }

    return true;
  });

  return (
    <main className="shell">
      <section className="card">
        <h1>Filterable User List</h1>
        <p className="subtitle">
          Search by name, filter by role, and show only active users.
        </p>

        <div className="controls">
          <div className="field">
            <label htmlFor="search">Search</label>
            <input
              id="search"
              type="text"
              placeholder="Search by name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="field">
            <label htmlFor="role">Role</label>
            <select
              id="role"
              value={selectedRole}
              onChange={(e) => setSelectedRole(e.target.value)}
            >
              <option value="all">All roles</option>
              <option value="admin">Admin</option>
              <option value="editor">Editor</option>
              <option value="viewer">Viewer</option>
            </select>
          </div>

          <label className="checkbox-field">
            <input
              type="checkbox"
              checked={showOnlyActive}
              onChange={(e) => setShowOnlyActive(e.target.checked)}
            />
            <span>Only active users</span>
          </label>
        </div>

        <ul className="list" aria-label="Filtered users">
          {filteredUsers.map((user) => (
            <li key={user.id} className="row">
              <div className="primary">{user.name}</div>
              <div className="meta">
                <span className="pill">{user.role}</span>
                <span className={user.active ? 'status' : 'status inactive'}>
                  {user.active ? 'Active' : 'Inactive'}
                </span>
              </div>
            </li>
          ))}

          {filteredUsers.length === 0 && (
            <li className="empty">No users match your filters.</li>
          )}
        </ul>
      </section>
    </main>
  );
}

