export default function App() {
  const [allowMultiple, setAllowMultiple] = React.useState(false);
  const [openIndexes, setOpenIndexes] = React.useState([]); // number[]

  const isItemOpen = (index) => openIndexes.includes(index);

  const onItemToggle = (index) => {
    const currentlyOpen = isItemOpen(index);

    if (allowMultiple) {
      setOpenIndexes((prev) =>
        currentlyOpen ? prev.filter((i) => i !== index) : [...prev, index]
      );
      return;
    }

    if (currentlyOpen) {
      setOpenIndexes([]);
    } else {
      setOpenIndexes([index]);
    }
  };

  const onToggleAllowMultiple = () => {
    setAllowMultiple((prev) => {
      const next = !prev;
      if (!next && openIndexes.length > 1) {
        // When going back to single-open, keep only the first open item
        setOpenIndexes((current) => (current.length ? [current[0]] : []));
      }
      return next;
    });
  };

  return (
    <main className="app-root">
      <section className="card">
        <header className="header">
          <h1>FAQ</h1>
          <label className="mode-toggle">
            <input
              type="checkbox"
              checked={allowMultiple}
              onChange={onToggleAllowMultiple}
            />
            <span>Allow multiple open</span>
          </label>
        </header>

        <div className="faq-list">
          {faqItems.map((item, index) => (
            <FaqItem
              key={item.question}
              question={item.question}
              answer={item.answer}
              isOpen={isItemOpen(index)}
              onToggle={() => onItemToggle(index)}
            />
          ))}
        </div>
      </section>
    </main>
  );
}

import React, { useState } from 'react';
import './App.css';
import { USERS, User } from './users';

const PAGE_SIZE = 5;

export default function App() {
  const [currentPage, setCurrentPage] = useState(0);

  const totalPages = Math.ceil(USERS.length / PAGE_SIZE) || 1;

  const start = currentPage * PAGE_SIZE;
  const end = start + PAGE_SIZE;
  const pagedUsers: User[] = USERS.slice(start, end);

  const isFirstPage = currentPage === 0;
  const isLastPage = currentPage >= totalPages - 1;

  const goPrevious = () => {
    setCurrentPage((page) => (page > 0 ? page - 1 : page));
  };

  const goNext = () => {
    setCurrentPage((page) => (page < totalPages - 1 ? page + 1 : page));
  };

  return (
    <main className="main">
      <section className="section">
        <header className="header">
          <div>
            <h1>Users (Pagination)</h1>
            <p className="subtitle">Simple paginated table (5 per page)</p>
          </div>
          <div className="meta">Total users: {USERS.length}</div>
        </header>

        <div className="panel">
          <table className="table" aria-label="Users table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Role</th>
              </tr>
            </thead>
            <tbody>
              {pagedUsers.map((user) => (
                <tr key={user.id}>
                  <td>{user.id}</td>
                  <td>{user.name}</td>
                  <td>{user.email}</td>
                  <td>{user.role}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <footer className="footer">
            <button
              type="button"
              className="ghost"
              onClick={goPrevious}
              disabled={isFirstPage}
            >
              Previous
            </button>
            <span className="page-info">
              Page {currentPage + 1} of {totalPages}
            </span>
            <button
              type="button"
              onClick={goNext}
              disabled={isLastPage}
            >
              Next
            </button>
          </footer>
        </div>
      </section>
    </main>
  );
}

