import React, { useState } from 'react';

function App() {
  const [currentStep, setCurrentStep] = useState(0); // 0, 1, 2
  const [form, setForm] = useState({
    basic: { name: '', email: '' },
    address: { street: '', city: '', country: '', postalCode: '' }
  });
  const [showErrors, setShowErrors] = useState(false);

  const { basic, address } = form;

  const basicErrors = {
    name: basic.name.trim().length === 0,
    email: basic.email.trim().length === 0
  };
  const isBasicValid = !basicErrors.name && !basicErrors.email;

  const addressErrors = {
    street: address.street.trim().length === 0,
    city: address.city.trim().length === 0,
    country: address.country.trim().length === 0
  };
  const isAddressValid = !addressErrors.street && !addressErrors.city && !addressErrors.country;

  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === 2;

  const canGoNext = currentStep === 0
    ? isBasicValid
    : currentStep === 1
      ? isAddressValid
      : false;

  function updateBasic(key, value) {
    setForm(prev => ({
      ...prev,
      basic: { ...prev.basic, [key]: value }
    }));
  }

  function updateAddress(key, value) {
    setForm(prev => ({
      ...prev,
      address: { ...prev.address, [key]: value }
    }));
  }

  function next() {
    if (!canGoNext) {
      setShowErrors(true);
      return;
    }
    setShowErrors(false);
    setCurrentStep(step => (step < 2 ? step + 1 : step));
  }

  function prev() {
    setShowErrors(false);
    setCurrentStep(step => (step > 0 ? step - 1 : step));
  }

  function submit() {
    const isValid = isBasicValid && isAddressValid;
    if (!isValid) {
      setShowErrors(true);
      if (!isBasicValid) setCurrentStep(0);
      else if (!isAddressValid) setCurrentStep(1);
      return;
    }
    console.log('Signup submitted', form);
  }

  // ...render steps and buttons using currentStep, showErrors, errors, next/prev/submit
  return <main>{/* UI omitted for brevity */}</main>;
}

