import React from 'react';

const FAKE_DATA = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Kim', email: 'charlie@example.com' },
  { id: 4, name: 'Diana Lopez', email: 'diana@example.com' },
  { id: 5, name: 'Ethan Brown', email: 'ethan@example.com' },
  { id: 6, name: 'Fiona Patel', email: 'fiona@example.com' }
];

function fakeApiSearch(term) {
  const trimmed = term.trim().toLowerCase();
  const delayMs = 600;

  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!trimmed) {
        resolve([]);
        return;
      }

      if (trimmed === 'error') {
        reject(new Error('Fake API error'));
        return;
      }

      const filtered = FAKE_DATA.filter((item) => {
        const name = item.name.toLowerCase();
        const email = item.email.toLowerCase();
        return name.includes(trimmed) || email.includes(trimmed);
      });

      resolve(filtered);
    }, delayMs);
  });
}

export default function App() {
  const [query, setQuery] = React.useState('');
  const [results, setResults] = React.useState([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState(null);

  React.useEffect(() => {
    let isCurrent = true;

    const trimmed = query.trim();
    if (!trimmed) {
      setResults([]);
      setIsLoading(false);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);

    const timeoutId = window.setTimeout(() => {
      fakeApiSearch(trimmed)
        .then((data) => {
          if (!isCurrent) return;
          setResults(data);
          setIsLoading(false);
        })
        .catch((err) => {
          if (!isCurrent) return;
          setResults([]);
          setIsLoading(false);
          setError(err instanceof Error ? err.message : 'Something went wrong.');
        });
    }, 500);

    return () => {
      isCurrent = false;
      window.clearTimeout(timeoutId);
    };
  }, [query]);

  const handleChange = (event) => {
    setQuery(event.target.value);
  };

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Debounced Search</h1>
          <p className="subtitle">
            Type to search a fake user directory. Search runs 500ms after you stop typing.
          </p>
        </header>

        <div className="field">
          <label className="label" htmlFor="search-input">Search</label>
          <input
            id="search-input"
            className="input"
            type="text"
            value={query}
            onChange={handleChange}
            placeholder="Start typing a name or email..."
            autoComplete="off"
          />
        </div>

        <div className="status-row">
          {isLoading && <span className="status status--loading">Searching…</span>}
          {!isLoading && !error && query && (
            <span className="status">Showing {results.length} result(s) for "{query}"</span>
          )}
          {!isLoading && !error && !query && (
            <span className="status status--muted">Start typing to search.</span>
          )}
          {error && <span className="status status--error">{error}</span>}
        </div>

        {results.length > 0 && (
          <ul className="results">
            {results.map((r) => (
              <li key={r.id} className="result-row">
                <div className="result-name">{r.name}</div>
                <div className="result-email">{r.email}</div>
              </li>
            ))}
          </ul>
        )}

