import React, { useState, useRef } from 'react';

function App() {
  const [children, setChildren] = useState([
    { label: 'Child 1', checked: false },
    { label: 'Child 2', checked: false },
    { label: 'Child 3', checked: false }
  ]);

  const parentRef = useRef(null);

  const syncParent = (nodes) => {
    const total = nodes.length;
    const checkedCount = nodes.filter((n) => n.checked).length;
    const parent = parentRef.current;
    if (!parent) return;

    if (checkedCount === total) {
      parent.checked = true;
      parent.indeterminate = false;
    } else if (checkedCount === 0) {
      parent.checked = false;
      parent.indeterminate = false;
    } else {
      parent.checked = false;
      parent.indeterminate = true;
    }
  };

  const toggleParent = (event) => {
    const checked = event.target.checked;
    setChildren((prev) => {
      const next = prev.map((child) => ({ ...child, checked }));
      syncParent(next);
      return next;
    });
  };

  const toggleChild = (index) => {
    setChildren((prev) => {
      const next = prev.map((child, i) =>
        i === index ? { ...child, checked: !child.checked } : child
      );
      syncParent(next);
      return next;
    });
  };

  return (
    <main style={{ minHeight: '100vh', background: '#0a0a0a', color: '#e5e7eb', display: 'grid', placeItems: 'center', padding: 24 }}>
      <section style={{ width: '100%', maxWidth: 420, display: 'grid', gap: 16 }}>
        <h1 style={{ margin: 0, fontSize: 20, fontWeight: 700 }}>Nested Checkboxes</h1>

        <div style={{ background: '#0b1020', border: '1px solid #1f2937', borderRadius: 12, padding: 16, display: 'grid', gap: 12 }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 16, fontWeight: 600 }}>
            <input ref={parentRef} type="checkbox" onChange={toggleParent} />
            <span>Parent</span>
          </label>

          <div style={{ display: 'grid', gap: 6, marginLeft: 24 }}>
            {children.map((child, index) => (
              <label key={child.label} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 14 }}>
                <input
                  type="checkbox"
                  checked={child.checked}
                  onChange={() => toggleChild(index)}
                />
                <span>{child.label}</span>
              </label>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}

