const SAMPLE_RESPONSE = "Sure! Here's a short streaming reply. It arrives token by token so the UI feels responsive.";

function startFakeStream(text, onChunk, onDone) {
  const tokens = text.split(' ');
  let i = 0;
  const id = window.setInterval(() => {
    const chunk = tokens[i] + (i < tokens.length - 1 ? ' ' : '');
    onChunk(chunk);
    i += 1;
    if (i >= tokens.length) {
      window.clearInterval(id);
      onDone();
    }
  }, 120);
  return () => window.clearInterval(id);
}

export default function App() {
  const [messages, setMessages] = React.useState([]);
  const [input, setInput] = React.useState('');
  const [isStreaming, setIsStreaming] = React.useState(false);

  const cancelRef = React.useRef(null);
  const streamIdRef = React.useRef(null);
  const idRef = React.useRef(0);

  const nextId = () => `m_${idRef.current++}`;

  React.useEffect(() => {
    return () => {
      if (cancelRef.current) cancelRef.current();
    };
  }, []);

  const stopStream = () => {
    if (cancelRef.current) {
      cancelRef.current();
      cancelRef.current = null;
    }
    if (streamIdRef.current) {
      const id = streamIdRef.current;
      streamIdRef.current = null;
      setMessages((prev) => prev.map((m) => (m.id === id ? { ...m, status: 'stopped' } : m)));
    }
    setIsStreaming(false);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const trimmed = input.trim();
    if (!trimmed || isStreaming) return;

    const userId = nextId();
    const assistantId = nextId();

    setMessages((prev) => [
      ...prev,
      { id: userId, role: 'user', text: trimmed, status: 'done' },
      { id: assistantId, role: 'assistant', text: '', status: 'streaming' }
    ]);

    setInput('');
    setIsStreaming(true);
    streamIdRef.current = assistantId;

    cancelRef.current = startFakeStream(
      SAMPLE_RESPONSE,
      (chunk) => {
        setMessages((prev) =>
          prev.map((m) => (m.id === assistantId ? { ...m, text: m.text + chunk } : m))
        );
      },
      () => {
        cancelRef.current = null;
        streamIdRef.current = null;
        setIsStreaming(false);
        setMessages((prev) =>
          prev.map((m) => (m.id === assistantId ? { ...m, status: 'done' } : m))
        );
      }
    );
  };

  return (
    <main className="chat-shell">
      <section className="chat-card">
        <header className="chat-header">
          <h1>Chat UI</h1>
          <p className="subtitle">Streaming assistant responses.</p>
        </header>

        <ul className="chat-list" aria-live="polite">
          {messages.map((m) => (
            <li key={m.id} className={`message message--${m.role}`}>
              <div className="message-role">{m.role === 'user' ? 'You' : 'Assistant'}</div>
              <div className="message-bubble">
                {m.text || (m.status === 'streaming' ? '...' : '')}
              </div>
            </li>
          ))}
          {messages.length === 0 && (
            <li className="empty">Start a conversation.</li>
          )}
        </ul>

        <form className="chat-input" onSubmit={handleSubmit}>
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask something..."
            disabled={isStreaming}
          />
          <button type="submit" disabled={isStreaming || !input.trim()}>
            Send
          </button>
          {isStreaming && (
            <button type="button" className="ghost" onClick={stopStream}>
              Stop
            </button>
          )}
        </form>
      </section>
    </main>
  );
}

import React, { useEffect, useState } from 'react';
import './App.css';

type Status = 'ready' | 'running' | 'paused' | 'done';

const DEFAULT_SECONDS = 10;

const STATUS_LABEL: Record<Status, string> = {
  ready: 'Ready',
  running: 'Running',
  paused: 'Paused',
  done: 'Done',
};

function formatTime(totalSeconds: number): string {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function clampSeconds(value: number): number {
  if (!Number.isFinite(value)) return 1;
  return Math.max(1, Math.min(5999, Math.floor(value)));
}

export default function App() {
  const [duration, setDuration] = useState(DEFAULT_SECONDS);
  const [remaining, setRemaining] = useState(DEFAULT_SECONDS);
  const [status, setStatus] = useState<Status>('ready');

  // One interval per running phase. Creating it inside the effect and clearing it in the
  // cleanup covers pause, reset, completion and unmount with a single code path.
  useEffect(() => {
    if (status !== 'running') return undefined;
    const id = window.setInterval(() => {
      setRemaining((value) => (value > 0 ? value - 1 : 0));
    }, 1000);
    return () => window.clearInterval(id);
  }, [status]);

  // Completion is derived from state, so the tick callback never has to know about status.
  useEffect(() => {
    if (status === 'running' && remaining === 0) setStatus('done');
  }, [remaining, status]);

  const start = () => {
    if (remaining > 0) setStatus('running');
  };

  const pause = () => {
    if (status === 'running') setStatus('paused');
  };

  const reset = () => {
    setRemaining(duration);
    setStatus('ready');
  };

  const changeDuration = (event: React.ChangeEvent<HTMLInputElement>) => {
    const next = clampSeconds(Number(event.target.value));
    setDuration(next);
    if (status !== 'running') {
      setRemaining(next);
      setStatus('ready');
    }
  };

  return (
    <main className="main">
      <section className="section">
        <h1>Countdown</h1>

        <div className="panel">
          <label className="field">
            <span>Seconds</span>
            <input
              id="duration"
              type="number"
              min={1}
              max={5999}
              value={duration}
              onChange={changeDuration}
              disabled={status === 'running'}
            />
          </label>

          <div className="value" aria-live="polite">{formatTime(remaining)}</div>
          <p className="status">{STATUS_LABEL[status]}</p>

          <div className="actions">
            <button onClick={start} disabled={status === 'running' || remaining === 0}>Start</button>
            <button onClick={pause} disabled={status !== 'running'}>Pause</button>
            <button onClick={reset} disabled={status === 'ready' && remaining === duration}>Reset</button>
          </div>
        </div>
      </section>
    </main>
  );
}

import React, { useEffect, useState } from 'react';
import './App.css';

export interface TeamMember {
  id: number;
  name: string;
  role: string;
}

export type SourceMode = 'ok' | 'empty' | 'flaky';

type RequestState =
  | { status: 'loading' }
  | { status: 'success'; members: TeamMember[] }
  | { status: 'empty' }
  | { status: 'error'; message: string };

const TEAM: TeamMember[] = [
  { id: 1, name: 'Alice Johnson', role: 'Frontend engineer' },
  { id: 2, name: 'Bob Smith', role: 'Product designer' },
  { id: 3, name: 'Charlie Kim', role: 'Backend engineer' },
  { id: 4, name: 'Diana Lopez', role: 'Engineering manager' },
  { id: 5, name: 'Ethan Brown', role: 'QA engineer' },
  { id: 6, name: 'Fiona Patel', role: 'Data analyst' }
];

let flakyRequests = 0;

// Fake API: responds after 400ms.
// - 'ok' resolves with the whole team
// - 'empty' resolves with an empty list
// - 'flaky' rejects every odd request, so the first request fails and a retry succeeds
export function fetchTeam(mode: SourceMode): Promise<TeamMember[]> {
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (mode === 'empty') {
        resolve([]);
        return;
      }

      if (mode === 'flaky') {
        flakyRequests += 1;
        if (flakyRequests % 2 === 1) {
          reject(new Error('Network timeout'));
          return;
        }
      }

      resolve(TEAM.map((member) => ({ ...member })));
    }, 400);
  });
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error && error.message ? error.message : 'Unknown error';
}

export default function App() {
  const [mode, setMode] = useState<SourceMode>('ok');
  const [attempt, setAttempt] = useState(0);
  const [request, setRequest] = useState<RequestState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    setRequest({ status: 'loading' });

    fetchTeam(mode)
      .then((members) => {
        if (cancelled) return;
        setRequest(members.length ? { status: 'success', members } : { status: 'empty' });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setRequest({ status: 'error', message: toErrorMessage(error) });
      });

    return () => {
      cancelled = true;
    };
  }, [mode, attempt]);

  function handleModeChange(event: React.ChangeEvent<HTMLSelectElement>) {
    setMode(event.target.value as SourceMode);
  }

  function handleRetry() {
    setAttempt((current) => current + 1);
  }

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Team Directory (Solution)</h1>
          <p className="subtitle">Load the team from a fake API and render every request state.</p>
        </header>

        <div className="field">
          <label className="label" htmlFor="mode-select">Data source</label>
          <select id="mode-select" className="mode" value={mode} onChange={handleModeChange}>
            <option value="ok">Team (6 members)</option>
            <option value="empty">Empty team</option>
            <option value="flaky">Flaky network</option>
          </select>
        </div>

        <div className="status-row">
          {request.status === 'loading' && <span className="status status--loading">Loading team…</span>}
          {request.status === 'success' && (
            <span className="status status--muted">{request.members.length} members</span>
          )}
          {request.status === 'empty' && <span className="status status--muted">0 members</span>}
          {request.status === 'error' && (
            <span className="status status--error" role="alert">
              Could not load the team: {request.message}
            </span>
          )}
        </div>

        {request.status === 'error' && (
          <button type="button" className="retry" onClick={handleRetry}>
            Retry
          </button>
        )}

        {request.status === 'success' && (
          <ul className="results">
            {request.members.map((member) => (
              <li key={member.id} className="user-row">
                <div className="user-name">{member.name}</div>
                <div className="user-role">{member.role}</div>
              </li>
            ))}
          </ul>
        )}

        {request.status === 'empty' && <p className="empty">No team members yet.</p>}
      </section>
    </main>
  );
}

import React, { useEffect, useState } from 'react';
import './App.css';

export interface Product {
  id: number;
  name: string;
  category: string;
}

export interface SearchResponse {
  items: Product[];
  total: number;
}

export const PAGE_SIZE = 5;

const CATALOG: Product[] = [
  { id: 1, name: 'Desk Lamp', category: 'Lighting' },
  { id: 2, name: 'Floor Lamp', category: 'Lighting' },
  { id: 3, name: 'Lamp Shade', category: 'Lighting' },
  { id: 4, name: 'Laptop Stand', category: 'Office' },
  { id: 5, name: 'Label Maker', category: 'Office' },
  { id: 6, name: 'Ladder Shelf', category: 'Furniture' },
  { id: 7, name: 'Lounge Chair', category: 'Furniture' },
  { id: 8, name: 'Linen Curtain', category: 'Textiles' },
  { id: 9, name: 'Wall Clock', category: 'Decor' },
  { id: 10, name: 'Table Runner', category: 'Textiles' },
  { id: 11, name: 'Bookend Pair', category: 'Decor' },
  { id: 12, name: 'Cable Tray', category: 'Office' }
];

// Fake search API. Treat it as given: the bugs are in App below.
// - resolves { items: the first PAGE_SIZE matches, total: the number of all matches }
// - one-letter queries answer slowly (600ms) and longer ones quickly (150ms),
//   so fast typing produces responses that arrive out of order
// - the query "error" rejects, like a search service that is down
export function searchProducts(query: string): Promise<SearchResponse> {
  const q = query.trim().toLowerCase();
  const delay = q.length === 1 ? 600 : 150;
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (q === 'error') {
        reject(new Error('Search service unavailable'));
        return;
      }
      const matches = CATALOG.filter((product) => product.name.toLowerCase().includes(q));
      resolve({ items: matches.slice(0, PAGE_SIZE), total: matches.length });
    }, delay);
  });
}

type SearchState =
  | { status: 'loading' }
  | { status: 'success'; items: Product[]; total: number }
  | { status: 'error'; message: string };

function toErrorMessage(error: unknown): string {
  return error instanceof Error && error.message ? error.message : 'Unknown error';
}

export default function App() {
  const [query, setQuery] = useState('');
  const [search, setSearch] = useState<SearchState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    setSearch({ status: 'loading' });

    searchProducts(query)
      .then((data: SearchResponse) => {
        if (cancelled) return;
        setSearch({ status: 'success', items: data.items, total: data.total });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setSearch({ status: 'error', message: toErrorMessage(error) });
      });

    return () => {
      cancelled = true;
    };
  }, [query]);

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Product Search (Solution)</h1>
          <p className="subtitle">Every search shows its own results, its own error and the total from the API.</p>
        </header>

        <div className="field">
          <label className="label" htmlFor="product-search">Search products</label>
          <input
            id="product-search"
            className="search"
            type="search"
            value={query}
            placeholder="Try lamp, desk or error"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => setQuery(event.target.value)}
          />
        </div>

        <div className="status-row">
          {search.status === 'loading' && <span className="status status--loading">Searching…</span>}
          {search.status === 'error' && (
            <span className="status status--error" role="alert">Search failed: {search.message}</span>
          )}
          {search.status === 'success' && search.total > 0 && (
            <span className="count">Showing {search.items.length} of {search.total} products</span>
          )}
        </div>

        {search.status === 'success' && search.total === 0 && (
          <p className="empty">No products match &quot;{query}&quot;.</p>
        )}

        {search.status === 'success' && search.total > 0 && (
          <ul className="results">
            {search.items.map((product) => (
              <li key={product.id} className="result-row">
                <div className="result-name">{product.name}</div>
                <div className="result-category">{product.category}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}

import React, { createContext, useCallback, useContext, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals. Reach any other hook through React,
// for example React.useLayoutEffect.

type CommonSelectProps = {
  label: string;
  placeholder?: string;
  className?: string;
  children: React.ReactNode;
};

type SingleSelectProps = CommonSelectProps & {
  multiple?: false;
  value: string | null;
  onChange: (value: string | null) => void;
};

type MultiSelectProps = CommonSelectProps & {
  multiple: true;
  value: string[];
  onChange: (value: string[]) => void;
};

export type SelectProps = SingleSelectProps | MultiSelectProps;

type SelectOptionProps = {
  value: string;
  label: string;
  disabled?: boolean;
  children?: React.ReactNode;
};

type SelectContextValue = {
  open: boolean;
  multiple: boolean;
  placeholder: string;
  selected: string[];
  labels: Map<string, string>;
  labelId: string;
  valueId: string;
  listboxId: string;
  toggleOpen: () => void;
  choose: (value: string) => void;
  registerOption: (value: string, label: string) => () => void;
};

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelectContext(part: string): SelectContextValue {
  const context = useContext(SelectContext);
  if (!context) {
    throw new Error(`<Select.${part}> must be rendered inside <Select>`);
  }
  return context;
}

let nextSelectId = 0;

function SelectRoot(props: SelectProps) {
  const { label, placeholder = 'Select…', className, children } = props;
  const [open, setOpen] = useState(false);
  const [labels, setLabels] = useState<Map<string, string>>(() => new Map());
  const idRef = useRef('');
  if (!idRef.current) {
    nextSelectId += 1;
    idRef.current = `select-${nextSelectId}`;
  }

  // `=== true` narrows the union even without strictNullChecks (off in the editor); a truthiness test does not.
  const selected = props.multiple === true ? props.value : props.value === null ? [] : [props.value];

  function choose(value: string) {
    if (props.multiple === true) {
      const next = props.value.includes(value)
        ? props.value.filter((item) => item !== value)
        : [...props.value, value];
      props.onChange(next);
      return;
    }
    props.onChange(value);
    setOpen(false);
  }

  const registerOption = useCallback((value: string, optionLabel: string) => {
    setLabels((current) => {
      if (current.get(value) === optionLabel) return current;
      const next = new Map(current);
      next.set(value, optionLabel);
      return next;
    });
    return () => {
      setLabels((current) => {
        if (!current.has(value)) return current;
        const next = new Map(current);
        next.delete(value);
        return next;
      });
    };
  }, []);

  const context: SelectContextValue = {
    open,
    multiple: Boolean(props.multiple),
    placeholder,
    selected,
    labels,
    labelId: `${idRef.current}-label`,
    valueId: `${idRef.current}-value`,
    listboxId: `${idRef.current}-listbox`,
    toggleOpen: () => setOpen((current) => !current),
    choose,
    registerOption
  };

  return (
    <SelectContext.Provider value={context}>
      <div
        className={['select', className].filter(Boolean).join(' ')}
        onKeyDown={(event: React.KeyboardEvent<HTMLDivElement>) => {
          if (event.key === 'Escape') setOpen(false);
        }}
      >
        <span className="select__label" id={context.labelId}>{label}</span>
        {children}
      </div>
    </SelectContext.Provider>
  );
}

function SelectTrigger() {
  const { open, selected, labels, placeholder, labelId, valueId, listboxId, toggleOpen } = useSelectContext('Trigger');
  const text = selected.length ? selected.map((value) => labels.get(value) ?? value).join(', ') : placeholder;
  return (
    <button
      type="button"
      className="select__trigger"
      aria-haspopup="listbox"
      aria-expanded={open}
      aria-controls={listboxId}
      aria-labelledby={`${labelId} ${valueId}`}
      onClick={toggleOpen}
    >
      <span className="select__value" id={valueId}>{text}</span>
    </button>
  );
}

function SelectOptions({ children }: { children: React.ReactNode }) {
  const { open, multiple, labelId, listboxId } = useSelectContext('Options');
  return (
    <ul
      id={listboxId}
      className="select__options"
      role="listbox"
      aria-labelledby={labelId}
      aria-multiselectable={multiple || undefined}
      hidden={!open}
    >
      {children}
    </ul>
  );
}

function SelectOption({ value, label, disabled = false, children }: SelectOptionProps) {
  const { selected, choose, registerOption } = useSelectContext('Option');
  React.useLayoutEffect(() => registerOption(value, label), [registerOption, value, label]);
  const isSelected = selected.includes(value);
  return (
    <li
      className="select__option"
      role="option"
      aria-selected={isSelected}
      aria-disabled={disabled || undefined}
      onClick={() => {
        if (!disabled) choose(value);
      }}
    >
      {children ?? label}
    </li>
  );
}

export const Select = Object.assign(SelectRoot, {
  Trigger: SelectTrigger,
  Options: SelectOptions,
  Option: SelectOption
});

const TOPPINGS = [
  { value: 'nuts', label: 'Nuts', icon: 'N' },
  { value: 'honey', label: 'Honey', icon: 'H' },
  { value: 'granola', label: 'Granola', icon: 'G' },
