import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals. This exercise asks you not to use useMemo.

export interface User {
  id: number;
  name: string;
  team: string;
}

const USERS: User[] = [
  { id: 1, name: 'Asha Rao', team: 'Checkout' },
  { id: 2, name: 'Ben Ortiz', team: 'Search' },
  { id: 3, name: 'Chen Wei', team: 'Payments' }
];

let requests = 0;
let failNext = false;

// Fake users API. Treat it as given.
// - resolves the three users after 300ms
// - rejects once after failNextRequest() is called
export function fetchUsers(): Promise<User[]> {
  requests += 1;
  const shouldFail = failNext;
  failNext = false;
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (shouldFail) {
        reject(new Error('Users service unavailable'));
        return;
      }
      resolve(USERS.map((user) => ({ ...user })));
    }, 300);
  });
}

export function failNextRequest(): void {
  failNext = true;
}

export function requestCount(): number {
  return requests;
}

export type UsersState =
  | { status: 'loading' }
  | { status: 'success'; users: User[] }
  | { status: 'error'; message: string };

export type UsersContextValue = {
  state: UsersState;
  reload: () => void;
};

function sameDeps(previous: readonly unknown[], next: readonly unknown[]): boolean {
  return previous.length === next.length && previous.every((dep, index) => Object.is(dep, next[index]));
}

function useMemoized<T>(factory: () => T, deps: readonly unknown[]): T {
  const cache = useRef<{ deps: readonly unknown[]; value: T } | null>(null);
  if (cache.current === null || !sameDeps(cache.current.deps, deps)) {
    cache.current = { deps, value: factory() };
  }
  return cache.current.value;
}

const UsersContext = createContext<UsersContextValue | null>(null);

function UsersProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<UsersState>({ status: 'loading' });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setState({ status: 'loading' });

    fetchUsers()
      .then((users) => {
        if (cancelled) return;
        setState({ status: 'success', users });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setState({ status: 'error', message: error instanceof Error ? error.message : 'Unknown error' });
      });

    return () => {
      cancelled = true;
    };
  }, [attempt]);

  const reload = useCallback(() => setAttempt((count) => count + 1), []);
  const value = useMemoized(() => ({ state, reload }), [state, reload]);

  return <UsersContext.Provider value={value}>{children}</UsersContext.Provider>;
}

function useUsers(): UsersContextValue {
  const context = useContext(UsersContext);
  if (!context) {
    throw new Error('useUsers must be used inside <UsersProvider>');
  }
  return context;
}

function UserSummary() {
  const { state } = useUsers();
  if (state.status === 'loading') return <p className="status status--loading">Loading users…</p>;
  if (state.status === 'error') {
    return <p className="status status--error" role="alert">Could not load users: {state.message}</p>;
  }
  return <p className="user-count">{state.users.length} users</p>;
}

function UserList() {
  const { state } = useUsers();
  if (state.status !== 'success') return null;
  return (
    <ul className="user-list">
      {state.users.map((user) => (
        <li key={user.id} className="user-row">
          <span className="user-name">{user.name}</span>
          <span className="user-team">{user.team}</span>
        </li>
      ))}
    </ul>
  );
}

function UsersToolbar() {
  const { reload } = useUsers();
  return (
    <div className="toolbar">
      <button type="button" className="reload" onClick={reload}>Reload</button>
      <button type="button" className="fail-next" onClick={failNextRequest}>Fail next request</button>
      <span className="request-count">Requests: {requestCount()}</span>
    </div>
  );
}

