import React, { useMemo, useState } from 'react';
import './App.css';

// Practice version of a reported take-home. The catalog, names and numbers are ours.
export type BatteryId = 'xl' | 'l' | 'm' | 's';

export interface Device {
  id: BatteryId | 'transformer';
  name: string;
  widthFt: number;
  energyMwh: number;
  costUsd: number;
}

export type Battery = Device & { id: BatteryId };

export const BATTERIES: Battery[] = [
  { id: 's', name: 'Battery S', widthFt: 10, energyMwh: 1, costUsd: 12000 },
  { id: 'm', name: 'Battery M', widthFt: 20, energyMwh: 2, costUsd: 48000 },
  { id: 'l', name: 'Battery L', widthFt: 30, energyMwh: 3, costUsd: 82000 },
  { id: 'xl', name: 'Battery XL', widthFt: 40, energyMwh: 4.2, costUsd: 125000 }
];

// A transformer is added automatically: one for every two batteries, rounded up.
export const TRANSFORMER: Device = { id: 'transformer', name: 'Transformer', widthFt: 10, energyMwh: -0.25, costUsd: 9000 };

export const SITE_WIDTH_FT = 100;
export const ROW_DEPTH_FT = 10;
export const MAX_QUANTITY = 50;

type Quantities = Record<BatteryId, string>;

const EMPTY_QUANTITIES: Quantities = { xl: '0', l: '0', m: '0', s: '0' };

function formatUsd(value: number): string {
  return '$' + value.toLocaleString('en-US');
}

function formatMwh(value: number): string {
  return `${Number(value.toFixed(2))} MWh`;
}

function parseQuantity(raw: string): number | null {
  const text = raw.trim();
  if (!/^\d+$/.test(text)) return null;
  const value = Number(text);
  return value <= MAX_QUANTITY ? value : null;
}

export function transformersFor(batteryCount: number): number {
  return Math.ceil(batteryCount / 2);
}

type Row = { widthFt: number; devices: Device[] };

export function packRows(devices: Device[], maxWidthFt: number = SITE_WIDTH_FT): Row[] {
  const largestFirst = [...devices].sort((a, b) => b.widthFt - a.widthFt);
  const rows: Row[] = [];
  for (const device of largestFirst) {
    const row = rows.find((candidate) => candidate.widthFt + device.widthFt <= maxWidthFt);
    if (row) {
      row.widthFt += device.widthFt;
      row.devices.push(device);
    } else {
      rows.push({ widthFt: device.widthFt, devices: [device] });
    }
  }
  return rows;
}

export default function App() {
  const [quantities, setQuantities] = useState<Quantities>(EMPTY_QUANTITIES);

  const site = useMemo(() => {
    const invalid = BATTERIES.filter((battery) => parseQuantity(quantities[battery.id]) === null).map((battery) => battery.id);
    const devices: Device[] = [];
    for (const battery of BATTERIES) {
      const count = parseQuantity(quantities[battery.id]) ?? 0;
      for (let i = 0; i < count; i += 1) devices.push(battery);
    }
    const transformers = transformersFor(devices.length);
    for (let i = 0; i < transformers; i += 1) devices.push(TRANSFORMER);

    const costUsd = devices.reduce((sum, device) => sum + device.costUsd, 0);
    const energyMwh = devices.reduce((sum, device) => sum + device.energyMwh, 0);
    const rows = packRows(devices);
    const widthFt = rows.reduce((widest, row) => Math.max(widest, row.widthFt), 0);
    const depthFt = rows.length * ROW_DEPTH_FT;
    return { invalid, transformers, costUsd, energyMwh, rows, widthFt, depthFt };
  }, [quantities]);

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Battery Site Planner (Solution)</h1>
          <p className="subtitle">Choose the batteries; the planner adds transformers, totals the site and lays it out.</p>
        </header>

        <section className="panel" aria-labelledby="devices-title">
          <h2 className="panel-title" id="devices-title">Batteries</h2>
          {BATTERIES.map((battery) => (
            <label key={battery.id} className="qty-field">
              <span className="qty-name">{battery.name}</span>
              <span className="qty-meta">{battery.widthFt} ft · {battery.energyMwh} MWh · {formatUsd(battery.costUsd)}</span>
              <input
                className="qty-input"
                data-device={battery.id}
                type="number"
                min={0}
                max={MAX_QUANTITY}
                step={1}
                value={quantities[battery.id]}
                onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                  setQuantities((current) => ({ ...current, [battery.id]: event.target.value }))
                }
              />
            </label>
          ))}
          {site.invalid.length > 0 && (
            <p className="qty-error" role="alert">Use a whole number from 0 to {MAX_QUANTITY}.</p>
          )}
          <button type="button" className="reset" onClick={() => setQuantities(EMPTY_QUANTITIES)}>Reset</button>
        </section>

        <section className="panel" aria-labelledby="summary-title">
          <h2 className="panel-title" id="summary-title">Site summary</h2>
          <dl className="summary">
            <dt>Budget</dt>
            <dd className="total-cost">{formatUsd(site.costUsd)}</dd>
            <dt>Net energy</dt>
            <dd className="total-energy">{formatMwh(site.energyMwh)}</dd>
            <dt>Land</dt>
            <dd className="land-size">{site.widthFt} ft × {site.depthFt} ft</dd>
          </dl>
          <p className="transformer-count">Transformers: {site.transformers}</p>
        </section>

        <section className="panel" aria-labelledby="layout-title">
          <h2 className="panel-title" id="layout-title">Layout (100 ft wide)</h2>
          <div className="layout">
            {site.rows.map((row, rowIndex) => (
              <div key={rowIndex} className="layout-row" data-width={row.widthFt}>
                {row.devices.map((device, deviceIndex) => (
                  <div
                    key={deviceIndex}
                    className="layout-device"
                    data-device={device.id}
                    style={{ width: `${(device.widthFt / SITE_WIDTH_FT) * 100}%` }}
                    title={device.name}
                  >
                    {device.id === 'transformer' ? 'T' : device.id.toUpperCase()}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </section>
      </section>
    </main>
  );
}

import React, { useCallback, useMemo, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals; write anything else as React.x.

export type FileNode = {
  id: string;
  name: string;
  children?: FileNode[];
};

// The project tree as the API returns it: unsorted. Treat it as given.
// A node with a children array is a folder, even when the array is empty.
export const FILES: FileNode[] = [
  { id: 'readme', name: 'README.md' },
  {
    id: 'src',
    name: 'src',
    children: [
      { id: 'index-tsx', name: 'index.tsx' },
      { id: 'styles', name: 'styles', children: [] },
      { id: 'app-tsx', name: 'App.tsx' },
      {
        id: 'components',
        name: 'components',
        children: [
          { id: 'tree-tsx', name: 'Tree.tsx' },
          { id: 'button-tsx', name: 'Button.tsx' },
        ],
      },
    ],
  },
  { id: 'package-json', name: 'package.json' },
  {
    id: 'public',
    name: 'public',
    children: [
      { id: 'index-html', name: 'index.html' },
      { id: 'favicon', name: 'favicon.ico' },
    ],
  },
];

type VisibleItem = {
  node: FileNode;
  path: string;
  level: number;
  parentId: string | null;
};

const isFolder = (node: FileNode): boolean => node.children !== undefined;

function sortNodes(nodes: FileNode[]): FileNode[] {
  return [...nodes].sort((a, b) => {
    if (isFolder(a) !== isFolder(b)) return isFolder(a) ? -1 : 1;
    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
  });
}

function buildParentMap(nodes: FileNode[], parentId: string | null, map: Map<string, string | null>) {
  for (const node of nodes) {
    map.set(node.id, parentId);
    if (node.children) buildParentMap(node.children, node.id, map);
  }
  return map;
}

const PARENT_OF = buildParentMap(FILES, null, new Map<string, string | null>());

function visibleItems(nodes: FileNode[], expanded: Set<string>, parent: VisibleItem | null): VisibleItem[] {
  return sortNodes(nodes).flatMap((node) => {
    const item: VisibleItem = {
      node,
      path: parent ? `${parent.path}/${node.name}` : node.name,
      level: parent ? parent.level + 1 : 1,
      parentId: parent ? parent.node.id : null,
    };
    const open = isFolder(node) && expanded.has(node.id);
    return open ? [item, ...visibleItems(node.children ?? [], expanded, item)] : [item];
  });
}

export default function App() {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string>(() => sortNodes(FILES)[0].id);
  const itemRefs = useRef(new Map<string, HTMLLIElement>());

  const visible = useMemo(() => visibleItems(FILES, expanded, null), [expanded]);

  // The tab stop must stay visible: if the active item sits inside a collapsed
  // folder, the nearest visible ancestor takes over.
  const tabStopId = useMemo(() => {
    const visibleIds = new Set(visible.map((item) => item.node.id));
    let id: string | null = activeId;
    while (id !== null && !visibleIds.has(id)) id = PARENT_OF.get(id) ?? null;
    return id ?? visible[0].node.id;
  }, [visible, activeId]);

  const focusItem = useCallback((id: string) => {
    setActiveId(id);
    itemRefs.current.get(id)?.focus();
  }, []);

  const toggle = useCallback((id: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const activate = (item: VisibleItem) => {
    if (isFolder(item.node)) toggle(item.node.id);
    else setSelectedPath(item.path);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLUListElement>) => {
    const target = (event.target as HTMLElement).closest('[role="treeitem"]');
    const index = visible.findIndex((item) => item.node.id === target?.getAttribute('data-id'));
    if (index < 0) return;
    const item = visible[index];
    const open = isFolder(item.node) && expanded.has(item.node.id);
    const next = visible[index + 1];

    switch (event.key) {
      case 'ArrowDown':
        if (next) focusItem(next.node.id);
        break;
      case 'ArrowUp':
        if (index > 0) focusItem(visible[index - 1].node.id);
        break;
      case 'Home':
        focusItem(visible[0].node.id);
        break;
      case 'End':
        focusItem(visible[visible.length - 1].node.id);
        break;
      case 'ArrowRight':
        if (isFolder(item.node) && !open) toggle(item.node.id);
        else if (open && next && next.parentId === item.node.id) focusItem(next.node.id);
        break;
      case 'ArrowLeft':
        if (open) toggle(item.node.id);
        else if (item.parentId) focusItem(item.parentId);
        break;
      case 'Enter':
        activate(item);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  const renderNodes = (nodes: FileNode[], parent: VisibleItem | null): React.ReactNode =>
    sortNodes(nodes).map((node) => {
      const item: VisibleItem = {
        node,
        path: parent ? `${parent.path}/${node.name}` : node.name,
        level: parent ? parent.level + 1 : 1,
        parentId: parent ? parent.node.id : null,
      };
      const folder = isFolder(node);
      const open = folder && expanded.has(node.id);
      return (
        <li
          key={node.id}
          role="treeitem"
          data-id={node.id}
          data-path={item.path}
          aria-level={item.level}
          aria-expanded={folder ? open : undefined}
          aria-selected={folder ? undefined : selectedPath === item.path}
          tabIndex={tabStopId === node.id ? 0 : -1}
          className={folder ? 'item item--folder' : 'item item--file'}
          ref={(element) => {
            if (element) itemRefs.current.set(node.id, element);
            else itemRefs.current.delete(node.id);
          }}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setActiveId(node.id);
          }}
        >
          <span
            className="row"
            style={{ paddingLeft: `${(item.level - 1) * 18 + 10}px` }}
            onClick={() => {
              focusItem(node.id);
              activate(item);
            }}
          >
            <span className="icon" aria-hidden="true">{folder ? (open ? '▾' : '▸') : '•'}</span>
            <span className="name">{node.name}</span>
          </span>
          {open && (
            <ul role="group">
              {node.children && node.children.length > 0 ? (
                renderNodes(node.children, item)
              ) : (
                <li role="none" className="empty" style={{ paddingLeft: `${item.level * 18 + 10}px` }}>
                  Empty folder
                </li>
              )}
            </ul>
          )}
        </li>
      );
    });

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Project files</h1>
          <p className="subtitle">Arrow keys move, Right opens, Left closes, Enter selects.</p>
        </header>
        <div className="toolbar">
          <button type="button" className="collapse-all" onClick={() => setExpanded(new Set())}>
            Collapse all
          </button>
          <p className="selection" aria-live="polite">
            {selectedPath ? `Selected: ${selectedPath}` : 'Nothing selected'}
          </p>
        </div>
        <ul role="tree" aria-label="Project files" className="tree" onKeyDown={onKeyDown}>
          {renderNodes(FILES, null)}
        </ul>
      </section>
    </main>
  );
}

import React, { useEffect, useReducer, useRef, useState } from 'react';
import './App.css';

type Basemap = {
  id: string;
  label: string;
};

// The last option is a user-named preset. Its name contains angle brackets on purpose.
const BASEMAPS: Basemap[] = [
  { id: 'satellite', label: 'Satellite' },
  { id: 'terrain', label: 'Terrain' },
  { id: 'streets', label: 'Streets' },
  { id: 'preset', label: 'My preset <draft>' }
];

type PickerState = {
  open: boolean;
  activeIndex: number;
  selectedIndex: number;
  count: number;
};

type PickerAction =
  | { type: 'toggle' }
  | { type: 'close' }
  | { type: 'choose'; index: number }
  | { type: 'key'; key: string };

type PickerOptions = {
  items: Basemap[];
  selectedId: string;
  idPrefix: string;
  label: string;
  onChange: (item: Basemap) => void;
};

function createPickerState(count: number, selectedIndex: number): PickerState {
  return { open: false, activeIndex: selectedIndex, selectedIndex, count };
}

function indexOfId(items: Basemap[], id: string): number {
  return Math.max(0, items.findIndex((item) => item.id === id));
}

// Shared logic: no DOM, no React and no callbacks, so both versions call it unchanged.
// It returns the same object when an action changes nothing.
function pickerReducer(state: PickerState, action: PickerAction): PickerState {
  switch (action.type) {
    case 'toggle':
      return state.open
        ? { ...state, open: false }
        : { ...state, open: true, activeIndex: state.selectedIndex };
    case 'close':
      return state.open ? { ...state, open: false } : state;
    case 'choose':
      return { ...state, open: false, activeIndex: action.index, selectedIndex: action.index };
    case 'key':
      return reduceKey(state, action.key);
  }
}

function reduceKey(state: PickerState, key: string): PickerState {
  if (!state.open) {
    // A closed picker opens on the selected option. Enter and Space reach the button's own click.
    return key === 'ArrowDown' || key === 'ArrowUp'
      ? { ...state, open: true, activeIndex: state.selectedIndex }
      : state;
  }
  const last = state.count - 1;
  switch (key) {
    case 'ArrowDown':
      return moveActive(state, Math.min(state.activeIndex + 1, last));
    case 'ArrowUp':
      return moveActive(state, Math.max(state.activeIndex - 1, 0));
    case 'Home':
      return moveActive(state, 0);
    case 'End':
      return moveActive(state, last);
    case 'Enter':
      return { ...state, open: false, selectedIndex: state.activeIndex };
    case 'Escape':
    case 'Tab':
      return { ...state, open: false };
    default:
      return state;
  }
}

function moveActive(state: PickerState, index: number): PickerState {
  return index === state.activeIndex ? state : { ...state, activeIndex: index };
}

// Keys the picker consumes, so the page does not scroll and the button does not click twice.
function handlesKey(state: PickerState, key: string): boolean {
  if (!state.open) return key === 'ArrowDown' || key === 'ArrowUp';
  return ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', 'Escape'].includes(key);
}

// Plain JavaScript version: builds its DOM once and updates it from one state object.
class BasemapPicker {
  private state: PickerState;
  private readonly options: PickerOptions;
  private readonly root: HTMLDivElement;
  private readonly trigger: HTMLButtonElement;
  private readonly list: HTMLUListElement;
  private readonly optionElements: HTMLLIElement[];

  constructor(host: HTMLElement, options: PickerOptions) {
    this.options = options;
    this.state = createPickerState(options.items.length, indexOfId(options.items, options.selectedId));

    this.root = document.createElement('div');
    this.root.className = 'picker';

    const label = document.createElement('span');
    label.id = `${options.idPrefix}-label`;
    label.className = 'picker-label';
    label.textContent = options.label;

    this.trigger = document.createElement('button');
    this.trigger.type = 'button';
    this.trigger.className = 'picker-trigger';
    this.trigger.setAttribute('role', 'combobox');
    this.trigger.setAttribute('aria-haspopup', 'listbox');
    this.trigger.setAttribute('aria-controls', `${options.idPrefix}-list`);
    this.trigger.setAttribute('aria-labelledby', label.id);

    this.list = document.createElement('ul');
    this.list.id = `${options.idPrefix}-list`;
    this.list.className = 'picker-list';
    this.list.setAttribute('role', 'listbox');
    this.list.setAttribute('aria-labelledby', label.id);

    this.optionElements = options.items.map((item, index) => {
      const option = document.createElement('li');
      option.id = `${options.idPrefix}-opt-${index}`;
      option.className = 'picker-option';
      option.setAttribute('role', 'option');
      option.dataset.index = String(index);
      // textContent, never innerHTML: labels can contain characters such as < and >.
      option.textContent = item.label;
      return option;
    });

    this.list.append(...this.optionElements);
    this.root.append(label, this.trigger, this.list);
    host.append(this.root);

    this.trigger.addEventListener('click', this.handleTriggerClick);
    this.trigger.addEventListener('keydown', this.handleTriggerKeyDown);
    this.list.addEventListener('click', this.handleListClick);
    document.addEventListener('click', this.handleDocumentClick);
    this.render();
  }

  destroy(): void {
    this.trigger.removeEventListener('click', this.handleTriggerClick);
    this.trigger.removeEventListener('keydown', this.handleTriggerKeyDown);
    this.list.removeEventListener('click', this.handleListClick);
    document.removeEventListener('click', this.handleDocumentClick);
    this.root.remove();
  }

  private handleTriggerClick = (): void => {
    this.send({ type: 'toggle' });
  };

  private handleTriggerKeyDown = (event: KeyboardEvent): void => {
    if (handlesKey(this.state, event.key)) event.preventDefault();
    this.send({ type: 'key', key: event.key });
  };

  // One listener for every option: event delegation.
  private handleListClick = (event: MouseEvent): void => {
    const option = (event.target as Element).closest<HTMLElement>('[role="option"]');
    if (!option || !this.list.contains(option)) return;
    this.send({ type: 'choose', index: Number(option.dataset.index) });
    this.trigger.focus();
  };

  private handleDocumentClick = (event: MouseEvent): void => {
    if (!this.root.contains(event.target as Node)) this.send({ type: 'close' });
  };

  private send(action: PickerAction): void {
    const previous = this.state;
    const next = pickerReducer(previous, action);
    if (next === previous) return;
    this.state = next;
    this.render();
    if (next.selectedIndex !== previous.selectedIndex) {
      this.options.onChange(this.options.items[next.selectedIndex]);
    }
  }

  // Updates the existing nodes in place, so the focused trigger is never replaced.
  private render(): void {
    const { open, activeIndex, selectedIndex } = this.state;
    this.trigger.textContent = this.options.items[selectedIndex].label;
    this.trigger.setAttribute('aria-expanded', String(open));
    if (open) {
      this.trigger.setAttribute('aria-activedescendant', this.optionElements[activeIndex].id);
    } else {
      this.trigger.removeAttribute('aria-activedescendant');
    }
    this.list.hidden = !open;
    this.optionElements.forEach((option, index) => {
      option.setAttribute('aria-selected', String(index === selectedIndex));
      option.classList.toggle('is-active', open && index === activeIndex);
    });
  }
}

// React version: the same reducer and DOM contract, with state, markup and listeners moved into React.
function ReactBasemapPicker({ items, selectedId, idPrefix, label, onChange }: PickerOptions) {
  const [state, dispatch] = useReducer(pickerReducer, null, () =>
    createPickerState(items.length, indexOfId(items, selectedId))
  );
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const { open, activeIndex, selectedIndex } = state;

  // The class adds this listener in its constructor and removes it in destroy(); here the effect
  // and its cleanup do the same. dispatch is stable, so the listener never reads stale state.
  useEffect(() => {
    function handleDocumentClick(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) dispatch({ type: 'close' });
    }
    document.addEventListener('click', handleDocumentClick);
    return () => document.removeEventListener('click', handleDocumentClick);
  }, []);

  // Side effects stay in event handlers: report a change only when the selection really changes.
  function send(action: PickerAction) {
    const next = pickerReducer(state, action);
    if (next === state) return;
    dispatch(action);
    if (next.selectedIndex !== state.selectedIndex) onChange(items[next.selectedIndex]);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    if (handlesKey(state, event.key)) event.preventDefault();
    send({ type: 'key', key: event.key });
  }

  function choose(index: number) {
    send({ type: 'choose', index });
    triggerRef.current?.focus();
  }

  const labelId = `${idPrefix}-label`;
  const listId = `${idPrefix}-list`;
  const optionId = (index: number) => `${idPrefix}-opt-${index}`;

  return (
    <div className="picker" ref={rootRef}>
      <span className="picker-label" id={labelId}>
        {label}
      </span>
      <button
        ref={triggerRef}
        type="button"
        className="picker-trigger"
        role="combobox"
        aria-haspopup="listbox"
        aria-controls={listId}
        aria-labelledby={labelId}
        aria-expanded={open}
        aria-activedescendant={open ? optionId(activeIndex) : undefined}
        onClick={() => send({ type: 'toggle' })}
        onKeyDown={handleKeyDown}
      >
        {items[selectedIndex].label}
      </button>
      <ul className="picker-list" id={listId} role="listbox" aria-labelledby={labelId} hidden={!open}>
        {items.map((item, index) => (
          <li
            key={item.id}
            id={optionId(index)}
            className={open && index === activeIndex ? 'picker-option is-active' : 'picker-option'}
            role="option"
            aria-selected={index === selectedIndex}
            onClick={() => choose(index)}
          >
            {item.label}
          </li>
        ))}
      </ul>
    </div>
  );
}

// Given: mounts the class version into a host element and destroys it on unmount.
function VanillaBasemapPicker(props: PickerOptions) {
  const hostRef = useRef<HTMLDivElement>(null);
  const onChangeRef = useRef(props.onChange);
  onChangeRef.current = props.onChange;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const picker = new BasemapPicker(host, { ...props, onChange: (item) => onChangeRef.current(item) });
    return () => picker.destroy();
    // The class owns its DOM after mount, so this wrapper mounts it once.
  }, []);

  return <div className="picker-host" ref={hostRef} />;
}

type ChangeLog = {
  label: string;
  changes: number;
};

function useChangeLog(initial: Basemap) {
  const [log, setLog] = useState<ChangeLog>({ label: initial.label, changes: 0 });
  const record = (item: Basemap) => setLog((current) => ({ label: item.label, changes: current.changes + 1 }));
  return [log, record] as const;
}

function Status({ log }: { log: ChangeLog }) {
  return (
    <p className="status" aria-live="polite">
      Selected <strong className="status-value">{log.label}</strong>, changes reported:{' '}
      <span className="status-count">{log.changes}</span>
    </p>
  );
}

export default function App() {
  const [vanillaLog, recordVanilla] = useChangeLog(BASEMAPS[0]);
  const [reactLog, recordReact] = useChangeLog(BASEMAPS[0]);

  return (
    <main className="main">
      <header className="header">
        <h1 className="title">Basemap Picker (Solution)</h1>
        <p className="subtitle">One picker written twice, as a plain JavaScript class and as a React component. Both pass the same checks.</p>
      </header>
      <div className="panels">
        <section className="panel" data-version="vanilla" aria-labelledby="vanilla-title">
          <h2 className="panel-title" id="vanilla-title">
            Plain JavaScript
          </h2>
          <VanillaBasemapPicker items={BASEMAPS} selectedId="satellite" idPrefix="vanilla-basemap" label="Basemap" onChange={recordVanilla} />
          <Status log={vanillaLog} />
        </section>
        <section className="panel" data-version="react" aria-labelledby="react-title">
          <h2 className="panel-title" id="react-title">
            React
          </h2>
          <ReactBasemapPicker items={BASEMAPS} selectedId="satellite" idPrefix="react-basemap" label="Basemap" onChange={recordReact} />
          <Status log={reactLog} />
        </section>
      </div>
    </main>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import './App.css';

export interface Line {
  id: number;
  text: string;
}

export type Language = 'en' | 'es';
export type Rate = 1 | 2;

/** Each transcript line plays for one second of audio; the clock ticks every 400 ms of real time. */
export const TICK_MS = 400;

const TRANSCRIPTS: Record<Language, Line[]> = {
  en: [
    { id: 1, text: 'Welcome to the dubbing review for episode four.' },
    { id: 2, text: 'The first voice sample mixes two speakers.' },
    { id: 3, text: 'Mark the lines where the timing drifts.' },
    { id: 4, text: 'The mix engineer joins after the break.' },
    { id: 5, text: 'Keep the pauses where the original pauses.' },
    { id: 6, text: 'Approve the take or request a new render.' },
    { id: 7, text: 'Export the approved mix to the project.' },
    { id: 8, text: 'Thanks, that is the end of the review.' }
  ],
  es: [
    { id: 1, text: 'Bienvenidos a la revisión del doblaje del episodio cuatro.' },
    { id: 2, text: 'La primera muestra de voz mezcla dos hablantes.' },
    { id: 3, text: 'Marquen las líneas donde el tiempo se desvía.' },
    { id: 4, text: 'El ingeniero de mezcla se une después de la pausa.' },
    { id: 5, text: 'Mantengan las pausas donde pausa el original.' },
    { id: 6, text: 'Aprueben la toma o pidan un nuevo render.' },
    { id: 7, text: 'Exporten la mezcla aprobada al proyecto.' },
    { id: 8, text: 'Gracias, ese es el final de la revisión.' }
  ]
};

// Fake transcript service. Treat it as given: the bugs are in App below.
// - Spanish answers slowly (700ms) and English quickly (150ms), so switching
//   there and back quickly produces responses that arrive out of order
export function loadTranscript(language: Language): Promise<Line[]> {
  const delay = language === 'es' ? 700 : 150;
  return new Promise((resolve) => {
    window.setTimeout(() => resolve(TRANSCRIPTS[language]), delay);
  });
}

export const LANGUAGE_NAMES: Record<Language, string> = { en: 'English', es: 'Spanish' };

export default function App() {
  const [language, setLanguage] = useState<Language>('en');
  const [lines, setLines] = useState<Line[]>([]);
  const [query, setQuery] = useState('');
  const [playing, setPlaying] = useState(false);
  const [rate, setRate] = useState<Rate>(1);
  const [position, setPosition] = useState(0);
  const total = lines.length;
  const finished = total > 0 && position >= total;

  useEffect(() => {
    let cancelled = false;
    setLines([]);
    loadTranscript(language).then((loaded) => {
      if (cancelled) return;
      setLines(loaded);
      setPosition(0);
    });
    return () => {
      cancelled = true;
    };
  }, [language]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return q ? lines.filter((line) => line.text.toLowerCase().includes(q)) : lines;
  }, [lines, query]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      setPosition((current) => Math.min(current + rate, total));
    }, TICK_MS);
    return () => {
      window.clearInterval(timer);
    };
  }, [playing, rate, total]);

  useEffect(() => {
    if (finished) setPlaying(false);
  }, [finished]);

  const activeIndex = Math.min(position, total - 1);
  const active = lines[activeIndex];
  const status = total === 0
    ? `Loading ${LANGUAGE_NAMES[language]}…`
    : finished
      ? 'Finished'
      : `${LANGUAGE_NAMES[language]} transcript`;

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Dubbing Review Player (Solution)</h1>
          <p className="subtitle">The clock follows the rate, pause stops it, the search filters at once and the latest language wins.</p>
        </header>

        <div className="controls">
          <button type="button" className="play" onClick={() => setPlaying((value) => !value)}>
            {playing ? 'Pause' : 'Play'}
          </button>
          <button
            type="button"
            className={`rate rate-1x${rate === 1 ? ' rate--active' : ''}`}
            onClick={() => setRate(1)}
          >
            1×
          </button>
          <button
            type="button"
            className={`rate rate-2x${rate === 2 ? ' rate--active' : ''}`}
            onClick={() => setRate(2)}
          >
            2×
          </button>
          <span className="time">{position.toFixed(1)} s</span>
        </div>

        <div className="controls">
          <button type="button" className="lang lang-en" onClick={() => setLanguage('en')}>English</button>
          <button type="button" className="lang lang-es" onClick={() => setLanguage('es')}>Spanish</button>
          <span className="status">{status}</span>
        </div>

        <div className="field">
          <label className="label" htmlFor="transcript-search">Search the transcript</label>
          <input
            id="transcript-search"
            className="search"
            type="search"
            value={query}
            placeholder="Try mix, pause or render"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => setQuery(event.target.value)}
          />
        </div>

        {total > 0 && (
          <span className="position">Line {activeIndex + 1} of {total}</span>
        )}

        <ol className="lines">
          {filtered.map((line) => (
            <li key={line.id} className={`line${active && active.id === line.id ? ' line--active' : ''}`}>
              {line.text}
            </li>
          ))}
        </ol>
      </section>
    </main>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import './App.css';

export interface FileRow {
  id: string;
  name: string;
  sizeKb: number;
  available: boolean;
}

export const PAGE_SIZE = 8;

/** Twenty-four files from a sensor export, two of them not yet available for download. */
export const FILES: FileRow[] = [
  { id: 'f01', name: 'agent-config-2026-10.json', sizeKb: 12, available: true },
  { id: 'f02', name: 'detections-report-q3.pdf', sizeKb: 2048, available: true },
