  { id: 'f04', name: 'incident-timeline.xlsx', sizeKb: 300, available: true },
  { id: 'f05', name: 'ioc-feed-latest.json', sizeKb: 96, available: false },
  { id: 'f06', name: 'kernel-telemetry-sample.bin', sizeKb: 8192, available: true },
  { id: 'f07', name: 'login-anomalies-report.pdf', sizeKb: 1536, available: true },
  { id: 'f08', name: 'network-flows-day1.csv', sizeKb: 4096, available: true },
  { id: 'f09', name: 'network-flows-day2.csv', sizeKb: 4100, available: true },
  { id: 'f10', name: 'policy-audit-report.pdf', sizeKb: 720, available: true },
  { id: 'f11', name: 'quarantine-log.txt', sizeKb: 48, available: true },
