  { id: 'f14', name: 'sensor-health-report.pdf', sizeKb: 880, available: true },
  { id: 'f15', name: 'threat-graph-export.json', sizeKb: 2560, available: true },
  { id: 'f16', name: 'user-sessions.csv', sizeKb: 512, available: true },
  { id: 'f17', name: 'vuln-scan-results.xml', sizeKb: 1024, available: true },
  { id: 'f18', name: 'weekly-summary-report.pdf', sizeKb: 400, available: true },
  { id: 'f19', name: 'api-keys-rotation.log', sizeKb: 8, available: true },
  { id: 'f20', name: 'cloud-posture-report.pdf', sizeKb: 1900, available: true },
  { id: 'f21', name: 'dns-queries.csv', sizeKb: 3072, available: true },
  { id: 'f22', name: 'endpoint-baseline.json', sizeKb: 256, available: true },
  { id: 'f23', name: 'firewall-rules.yaml', sizeKb: 64, available: true },
  { id: 'f24', name: 'malware-samples-index.csv', sizeKb: 128, available: true }
];

type SortKey = 'name' | 'size';

/** Selection as a mode plus exceptions, so select all never needs every id in memory. */
interface Selection {
  mode: 'none' | 'all';
  exceptions: Set<string>;
}

function formatSize(sizeKb: number): string {
  return sizeKb >= 1024 ? `${(sizeKb / 1024).toFixed(1)} MB` : `${sizeKb} KB`;
}

export default function App() {
  const [filter, setFilter] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('name');
  const [page, setPage] = useState(1);
  const [selection, setSelection] = useState<Selection>({ mode: 'none', exceptions: new Set() });
  const headerRef = useRef<HTMLInputElement>(null);

  const matching = useMemo(() => {
    const q = filter.trim().toLowerCase();
    const rows = q ? FILES.filter((file) => file.name.toLowerCase().includes(q)) : FILES;
    return [...rows].sort((a, b) => (sortKey === 'name' ? a.name.localeCompare(b.name) : a.sizeKb - b.sizeKb));
  }, [filter, sortKey]);

  const pageCount = Math.max(1, Math.ceil(matching.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = matching.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);
  const selectable = matching.filter((file) => file.available);

  const isSelected = (file: FileRow) =>
    file.available && (selection.mode === 'all' ? !selection.exceptions.has(file.id) : selection.exceptions.has(file.id));
  const selectedCount = selectable.filter(isSelected).length;
  const headerState: 'none' | 'some' | 'all' =
    selectedCount === 0 ? 'none' : selectedCount === selectable.length ? 'all' : 'some';

  useEffect(() => {
    if (headerRef.current) headerRef.current.indeterminate = headerState === 'some';
  }, [headerState]);

  const toggleAll = () => {
    setSelection(headerState === 'all' ? { mode: 'none', exceptions: new Set() } : { mode: 'all', exceptions: new Set() });
  };

  const toggleRow = (file: FileRow) => {
    setSelection((current) => {
      const exceptions = new Set(current.exceptions);
      if (exceptions.has(file.id)) exceptions.delete(file.id);
      else exceptions.add(file.id);
      return { mode: current.mode, exceptions };
    });
  };

  const changeFilter = (value: string) => {
    setFilter(value);
    setPage(1);
    setSelection({ mode: 'none', exceptions: new Set() });
  };

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Downloadable Files (Solution)</h1>
          <p className="subtitle">Select all follows the filter and survives paging, sorting and a few deselections.</p>
        </header>

        <div className="toolbar">
          <label className="label" htmlFor="file-filter">Filter by name</label>
          <input
            id="file-filter"
            className="filter"
            type="search"
            value={filter}
            placeholder="Try report, csv or flows"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) => changeFilter(event.target.value)}
          />
          <button type="button" className="sort-name" aria-pressed={sortKey === 'name'} onClick={() => setSortKey('name')}>
            Sort by name
          </button>
          <button type="button" className="sort-size" aria-pressed={sortKey === 'size'} onClick={() => setSortKey('size')}>
            Sort by size
          </button>
        </div>

        <div className="summary">
          <span className="selection-count">{selectedCount} selected</span>
          <button type="button" className="download" disabled={selectedCount === 0}>
            Download selected
          </button>
        </div>

        {matching.length === 0 ? (
          <p className="empty">No files match &quot;{filter}&quot;.</p>
        ) : (
          <div className="table-scroll">
            <table className="files">
              <caption className="caption">Files matching the filter, page {currentPage} of {pageCount}</caption>
              <thead>
                <tr>
                  <th scope="col" className="col-select">
                    <input
                      ref={headerRef}
                      type="checkbox"
                      className="select-all"
                      aria-label="Select all matching files"
                      aria-checked={headerState === 'some' ? 'mixed' : headerState === 'all'}
                      checked={headerState === 'all'}
                      onChange={toggleAll}
                    />
                  </th>
                  <th scope="col">Name</th>
                  <th scope="col">Size</th>
                  <th scope="col">Status</th>
                </tr>
              </thead>
              <tbody>
                {visible.map((file) => (
                  <tr key={file.id} className={`row${isSelected(file) ? ' row--selected' : ''}`}>
                    <td>
                      <input
                        type="checkbox"
                        className="select-row"
                        aria-label={`Select ${file.name}`}
                        checked={isSelected(file)}
                        disabled={!file.available}
                        onChange={() => toggleRow(file)}
                      />
                    </td>
                    <td className="name">{file.name}</td>
                    <td className="size">{formatSize(file.sizeKb)}</td>
                    <td className={`status${file.available ? '' : ' status--unavailable'}`}>
                      {file.available ? 'Available' : 'Not available yet'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <div className="pager">
          <button type="button" className="prev" disabled={currentPage <= 1} onClick={() => setPage(currentPage - 1)}>
            Previous
          </button>
          <span className="page">Page {currentPage} of {pageCount}</span>
          <button type="button" className="next" disabled={currentPage >= pageCount} onClick={() => setPage(currentPage + 1)}>
            Next
          </button>
        </div>
      </section>
    </main>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import './App.css';

export interface BookedRange {
  /** The first booked night, as an ISO date. */
  from: string;
  /** The check-out day after the last booked night, so a range is half-open. */
  to: string;
}

export interface Listing {
  name: string;
  currency: string;
  nightlyPrice: number;
  cleaningFee: number;
  includedGuests: number;
  extraGuestFee: number;
  maxGuests: number;
  booked: BookedRange[];
}

/** One listing; every price is in whole units of its currency. */
export const LISTING: Listing = {
  name: 'Lakeside cabin',
  currency: 'USD',
  nightlyPrice: 180,
  cleaningFee: 60,
  includedGuests: 2,
  extraGuestFee: 25,
  maxGuests: 4,
  booked: [{ from: '2026-12-24', to: '2026-12-27' }],
};

/** Exchange rates from the listing currency, for the currency follow-up. */
export const RATES: Record<string, number> = { USD: 1, EUR: 0.92 };

const DAY_MS = 86_400_000;
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Whole days since the epoch in UTC, so a stay never gains or loses a night across a clock change. */
const toDay = (iso: string) => Date.UTC(Number(iso.slice(0, 4)), Number(iso.slice(5, 7)) - 1, Number(iso.slice(8, 10))) / DAY_MS;

const money = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: LISTING.currency,
  minimumFractionDigits: 0,
  maximumFractionDigits: 0,
});
const shortDate = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const showDate = (iso: string) => shortDate.format(new Date(`${iso}T00:00:00Z`));
const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? '' : 's'}`;

type Quote =
  | { kind: 'empty' }
  | { kind: 'invalid'; message: string }
  | { kind: 'booked'; message: string }
  | { kind: 'ready'; nights: number; nightly: number; stay: number; total: number };

interface CounterProps {
  name: string;
  className: string;
  value: number;
  min: number;
  canAdd: boolean;
  onChange: (value: number) => void;
}

function Counter({ name, className, value, min, canAdd, onChange }: CounterProps) {
  const noun = name.toLowerCase();
  return (
    <div className={`counter ${className}`}>
      <span className="counter-name">{name}</span>
      <button type="button" className={`step ${className}-minus`} aria-label={`Remove one from ${noun}`} disabled={value <= min} onClick={() => onChange(value - 1)}>
        -
      </button>
      <output className={`${className}-count`} aria-live="polite">{value}</output>
      <button type="button" className={`step ${className}-plus`} aria-label={`Add one to ${noun}`} disabled={!canAdd} onClick={() => onChange(value + 1)}>
        +
      </button>
    </div>
  );
}

export default function App() {
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [adults, setAdults] = useState(1);
  const [children, setChildren] = useState(0);
  const [confirming, setConfirming] = useState(false);
  const [bookedMessage, setBookedMessage] = useState('');
  const bookRef = useRef<HTMLButtonElement>(null);
  const confirmRef = useRef<HTMLButtonElement>(null);
  const messageRef = useRef<HTMLParagraphElement>(null);
  const guests = adults + children;

  // One derived quote: every line, the total and the button read it, so they can never disagree.
  const quote = useMemo<Quote>(() => {
    if (!ISO_DATE.test(checkIn) || !ISO_DATE.test(checkOut)) return { kind: 'empty' };
    const nights = toDay(checkOut) - toDay(checkIn);
    if (nights <= 0) return { kind: 'invalid', message: 'Check-out must be after check-in' };
    // Half-open ranges: a stay that checks out on the day a booking starts does not overlap it.
    if (LISTING.booked.some((range) => checkIn < range.to && range.from < checkOut)) {
      return { kind: 'booked', message: 'Those dates are booked' };
    }
    const nightly = LISTING.nightlyPrice + Math.max(0, guests - LISTING.includedGuests) * LISTING.extraGuestFee;
    const stay = nightly * nights;
    return { kind: 'ready', nights, nightly, stay, total: stay + LISTING.cleaningFee };
  }, [checkIn, checkOut, guests]);

  const canBook = quote.kind === 'ready' && !bookedMessage;

  useEffect(() => {
    if (confirming) confirmRef.current?.focus();
  }, [confirming]);

  useEffect(() => {
    if (bookedMessage) messageRef.current?.focus();
  }, [bookedMessage]);

  const closeDialog = () => {
    setConfirming(false);
    bookRef.current?.focus();
  };

  const confirmBooking = () => {
    if (quote.kind !== 'ready') return;
    setConfirming(false);
    setBookedMessage(`Booked: ${LISTING.name}, ${showDate(checkIn)} to ${showDate(checkOut)}`);
  };

  return (
    <main className="main">
      <section className="card" aria-labelledby="listing-title">
        <header className="header">
          <h1 id="listing-title" className="title">{LISTING.name}</h1>
          <p className="subtitle">
            {money.format(LISTING.nightlyPrice)} a night for {LISTING.includedGuests} guests · up to {LISTING.maxGuests} guests
          </p>
        </header>

        <div className="dates">
          <label className="field">
            <span className="label">Check-in</span>
            <input className="check-in" type="date" value={checkIn} onChange={(event) => setCheckIn(event.target.value)} />
          </label>
          <label className="field">
            <span className="label">Check-out</span>
            <input className="check-out" type="date" value={checkOut} onChange={(event) => setCheckOut(event.target.value)} />
          </label>
        </div>

        <fieldset className="guests">
          <legend className="label">Guests</legend>
          <Counter name="Adults" className="adults" value={adults} min={1} canAdd={guests < LISTING.maxGuests} onChange={setAdults} />
          <Counter name="Children" className="children" value={children} min={0} canAdd={guests < LISTING.maxGuests} onChange={setChildren} />
        </fieldset>

        {quote.kind === 'invalid' && <p className="date-error" role="alert">{quote.message}</p>}
        {quote.kind === 'booked' && <p className="availability" role="status">{quote.message}</p>}
        {quote.kind === 'ready' && (
          <dl className="breakdown">
            <div className="line">
              <dt className="price-line">{money.format(quote.nightly)} x {plural(quote.nights, 'night')}</dt>
              <dd className="price-amount">{money.format(quote.stay)}</dd>
            </div>
            <div className="line">
              <dt>Cleaning fee</dt>
              <dd className="cleaning-fee">{money.format(LISTING.cleaningFee)}</dd>
            </div>
            <div className="line line--total">
              <dt>Total</dt>
              <dd className="total">{money.format(quote.total)}</dd>
            </div>
          </dl>
        )}

        <button ref={bookRef} type="button" className="book" disabled={!canBook} onClick={() => setConfirming(true)}>
          Book now
        </button>
        {bookedMessage && (
          <p ref={messageRef} className="booked-message" role="status" tabIndex={-1}>
            {bookedMessage}
          </p>
        )}

        {confirming && quote.kind === 'ready' && (
          <div className="backdrop">
            <div
              className="confirm-dialog"
              role="dialog"
              aria-modal="true"
              aria-labelledby="confirm-title"
              onKeyDown={(event) => {
                if (event.key === 'Escape') closeDialog();
              }}
            >
              <h2 id="confirm-title" className="dialog-title">Confirm your stay</h2>
              <p className="confirm-summary">
                {showDate(checkIn)} to {showDate(checkOut)} · {plural(quote.nights, 'night')} · {plural(guests, 'guest')} · {money.format(quote.total)}
              </p>
              <div className="dialog-actions">
                <button type="button" className="cancel" onClick={closeDialog}>
                  Cancel
                </button>
                <button ref={confirmRef} type="button" className="confirm" onClick={confirmBooking}>
                  Confirm booking
                </button>
              </div>
            </div>
          </div>
        )}
      </section>
    </main>
  );
}
